<?php
namespace Database\Seeders;
use App\Models\Permission; use App\Models\Role; use App\Models\User; use Illuminate\Database\Seeder;
class AdminSeeder extends Seeder { public function run():void { $tenant=env('ADMIN_TENANT_ID','00000000-0000-4000-8000-000000000001'); $names=['users.view','users.create','users.update','users.delete','roles.view','audit.view','customer.view','customer.create','customer.update','customer.delete','customer.bulk','customer.export','vehicle.view','vehicle.create','vehicle.update','vehicle.delete','vehicle.bulk','vehicle.export']; $permissions=collect($names)->map(fn($name)=>Permission::firstOrCreate(['name'=>$name],['description'=>ucfirst(str_replace('.',' ',$name))])); $role=Role::firstOrCreate(['tenant_id'=>$tenant,'slug'=>'administrator'],['name'=>'Administrator']); $role->permissions()->sync($permissions->pluck('id')); $admin=User::updateOrCreate(['tenant_id'=>$tenant,'email'=>strtolower(env('ADMIN_EMAIL','admin@example.com'))],['name'=>env('ADMIN_NAME','Development Admin'),'password'=>env('ADMIN_PASSWORD','password'),'is_admin'=>true,'is_active'=>true,'email_verified_at'=>now()]); $admin->roles()->syncWithoutDetaching([$role->id]); } }
